True def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    vertical = [c for c in range(w) if all(g[r][c] == 2 for r in range(h))]
    horizontal = [r for r in range(h) if all(v == 2 for v in g[r])]

    if vertical:
        divider = vertical[0]
        colors = {v for row in g for v in row if v != 2}
        background = max(colors, key=lambda color: sum(v == color for row in g for v in row))
        points = [(r, c) for r in range(h) for c in range(w) if g[r][c] not in (2, background)]
        if points:
            left = min(c for r, c in points)
            right = max(c for r, c in points)
            target = right + 1 if left > divider else left - 1
            if 0 <= target < w:
                for r in range(h):
                    if g[r][target] == background:
                        g[r][target] = 8
        return g

    if horizontal:
        divider = horizontal[0]
        colors = {v for row in g for v in row if v != 2}
        background = max(colors, key=lambda color: sum(v == color for row in g for v in row))
        points = [(r, c) for r in range(h) for c in range(w) if g[r][c] not in (2, background)]
        if points:
            top = min(r for r, c in points)
            bottom = max(r for r, c in points)
            target = bottom + 1 if top > divider else top - 1
            if 0 <= target < h:
                for c in range(w):
                    if g[target][c] == background:
                        g[target][c] = 8
        return g

    return g
